    function isActivityComplete(key) {
        return _state.scores[key] && _state.scores[key].complete;
    }

    function countComplete() {
        return ACTIVITIES.filter(a => isActivityComplete(a.key)).length;
    }

    function esc(str) {
        return String(str == null ? '' : str).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
    }

    function cleanWord(w) {
        return String(w || '').toLowerCase().replace(/[^a-z0-9']/g, '');
    }

    function isSet(v) {
        return v !== undefined && v !== null;
    }

    function praise(i) {
        return ENCOURAGING_PRAISES[i % ENCOURAGING_PRAISES.length];
    }

    function celebrate() {
        if (typeof confetti === 'function') {
            confetti({ particleCount: 90, spread: 70, origin: { y: 0.6 }, colors: ['#7C3AED', '#FACC15', '#0EA5E9', '#EC4899', '#F97316'] });
        }
    }

    function prepTag(p) {
        return `<span class="c14p-tag c14p-tag-${p}">${PREP_INFO[p].icon} ${PREP_INFO[p].label}</span>`;
    }

    // Highlights at / on / in in a sentence (shape + colour, the word stays readable)
    function markPreps(text) {
        return esc(text).replace(/\b(at|on|in|At|On|In)\b/g, m => `<b class="c14p-prep c14p-prep-${m.toLowerCase()}">${m}</b>`);
    }

    function blankSentence(sentence, filled, state) {
        const cls = state === true ? ' correct' : state === false ? ' wrong' : '';
        return esc(sentence).replace('___', `<span class="c3p-blank${cls}">${filled ? esc(filled) : '______'}</span>`);
    }

    // Shared feedback box built on the existing c1p-feedback-box styles
    function feedbackBox(kind, icon, title, text, buttons) {
        const cls = kind === 'correct' ? 'c1p-fb-correct' : kind === 'partial' ? 'c1p-fb-partial' : 'c1p-fb-wrong';
        return `
            <div class="c1p-feedback-box ${cls} c3p-feedback" role="status">
                <span class="c1p-fb-icon">${icon}</span>
                <div class="c1p-fb-text">
                    <strong>${title}</strong>
                    <div class="c3p-fb-body">${text}</div>
                </div>
                <div class="c3p-fb-actions">${buttons || ''}</div>
            </div>
        `;
    }

