        kind: { syn: ['nice', 'gentle', 'caring', 'friendly'], ant: ['mean', 'unkind', 'cruel'] },
        sad: { syn: ['unhappy', 'upset', 'gloomy'], ant: ['happy', 'joyful', 'glad'] },
