    const CHOOSE_QS = [
        { kind: 'pick', sentence: "___, I found a shiny stone.", options: ['Finally', 'First', 'In the end'], answer: 'First', why: "“First” tells what happens at the start of the tale." },
        { kind: 'pick', sentence: "I found a shiny stone. ___, the stone suddenly began to glow.", options: ['Then', 'First', 'Finally'], answer: 'Then', why: "Then tells us what happens next." },
        { kind: 'pick', sentence: "The stone was glowing. ___, the stone led me home.", options: ['First', 'Finally', 'Suddenly'], answer: 'Finally', why: "“Finally” tells the last thing that happens: the stone leads the way home." },
        { kind: 'pick', sentence: "The fox wandered into the forest. ___, it met a friendly owl.", options: ['After that', 'First', 'In the end'], answer: 'After that', why: "“After that” shows the owl came next, after the fox got lost." },
        { kind: 'pick', sentence: "The owl showed the fox the way. ___, the fox found its family again.", options: ['First', 'At last', 'Next'], answer: 'At last', why: "“At last” tells the happy ending, after a long wait." },
        { kind: 'pick', sentence: "The dragon discovered a cave. ___, a puzzle blocked his path.", options: ['Suddenly', 'First', 'In the end'], answer: 'Suddenly', why: "“Suddenly” shows a surprise: a puzzle appears out of nowhere!" },
        { kind: 'type', sentence: "Aanya said: “First, you find the stone. ___, something surprising happens.”", accept: ['then', 'next', 'after that', 'suddenly'], answer: 'Then', why: "The surprise comes next, so a middle word fits: Then, Next or After that.", hint: "What happens after you find the stone? Use a word from the middle of a story." },
        { kind: 'type', sentence: "Nima said: “First, then, after that, ___.”", accept: ['finally', 'at last', 'in the end'], answer: 'Finally', why: "Nima finished her stepping stones with an end word: Finally.", hint: "Nima is at the last stepping stone. Which word finishes a story?" }
    ].map(q => ({ ...q, hint: q.hint || `Is this the start, the middle, or the end of the tale? Pick a ${q.kind === 'pick' ? WORD_INFO[q.answer.toLowerCase()].part : 'middle'} word.` }));

